    "explanation": "solution/solve.sh outputs final report deliverables using bare heredocs/cat without performing any actual DFIR analysis or computational commands."
  },
  "separate_verifier_configured": {
    "outcome": "fail",
    "explanation": "Separate verifier mode is not configured: task.toml lacks environment_mode = \"separate\", tests/Dockerfile does not exist, and no artifacts are declared."
  },
  "environment_hygiene": {
    "outcome": "fail",
    "explanation": "Without separate-verifier mode and tests/Dockerfile, tests and solution files leak into the agent environment rather than being isolated in a verifier image."
