    "explanation": "The difficulty_explanation metadata field is missing from task.toml."
  },
  "solution_explanation_quality": {
    "outcome": "fail",
    "explanation": "The solution_explanation metadata field is missing from task.toml."
  },
  "verification_explanation_quality": {
    "outcome": "fail",
    "explanation": "The verification_explanation metadata field is missing from task.toml."
  },
  "category_and_tags": {
    "outcome": "fail",
    "explanation": "The subcategory metadata field is missing from task.toml."
  },
  "task_name": {
    "outcome": "pass",
    "explanation": "The task name 'ssh-miner' is descriptive, kebab-case, and at most 3 words."
  },
  "resource_configuration": {
    "outcome": "pass",
    "explanation": "Timeouts and environment resource limits are appropriate for a long-horizon DFIR task."
  },
  "task_readme": {
    "outcome": "pass",
    "explanation": "environment/README.md provides useful context without duplicating instructions or task metadata."
  },
  "expert_time_estimate": {
    "outcome": "fail",
    "explanation": "The expert_time_estimate_hours metadata field is missing from task.toml."
  },
  "task_toml_schema": {
    "outcome": "fail",
    "explanation": "task.toml contains the unrecognised field 'difficulty = \"hard\"' under [metadata] and lacks required benchmark metadata fields."
  },
  "no_extraneous_files": {
    "outcome": "fail",
    "explanation": "The task directory contains unused development assets in assets/ and baselines/ that are not referenced or required by Dockerfiles, solution, instruction, or tests."
  },
  "artifact_efficiency": {
    "outcome": "not_applicable",
    "explanation": "Separate verifier mode and artifacts are not configured for this task."
  },
  "verifier_execution_isolation": {
    "outcome": "not_applicable",
    "explanation": "The verifier only parses static markdown reports produced by the agent and does not execute agent code or binaries."
  },
  "ctrf_reporting": {
    "outcome": "fail",
    "explanation": "The custom rewardkit verifier runs discrete checks across criteria files but does not output a CTRF report to /logs/verifier/ctrf.json."
  },
  "do_not_modify_enforced": {
    "outcome": "pass",
    "explanation": "The /disk and /sas evidence directories are read-only and modifications do not help bypass verification."
  },
  "binary_reward": {
    "outcome": "pass",
    "explanation": "The verifier explicitly thresholds passed conditions and writes exactly 1.0 or 0.0 to /logs/verifier/reward.txt."
  }
}
EOF
",
      "duration": 0.5
    }
  ]
}

